/**
 * Centralized formatting utilities
 * Eliminates duplication of date/phone/currency formatting across components.
 */
import { formatDistanceToNow, format, isToday, isYesterday } from 'date-fns';
import { ptBR } from 'date-fns/locale';

// ─── Date Formatting ────────────────────────────────────────────────

/**
 * Marcador único de "sem dado" para data inválida — a mesma linguagem usada
 * no resto da UI. O date-fns (`format`/`formatDistanceToNow`) lança
 * `RangeError: Invalid time value` quando recebe uma Data inválida, o que
 * derrubaria o componente inteiro; quem formata data nunca deixa isso passar.
 */
const DATA_INVALIDA = '—';

/**
 * Converte a entrada em `Date` só quando ela é uma data de verdade.
 * Devolve `null` para string vazia/só espaços, texto livre, `null`/`undefined`,
 * `Date` inválido ou número fora da faixa representável — casos em que o
 * construtor silenciosamente devolveria uma data errada (ex.: `null` → epoch)
 * ou `Invalid Date`.
 */
function toValidDate(value: Date | string | number | null | undefined): Date | null {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * Format a date as relative time in Portuguese (e.g., "há 5 minutos").
 * `addSuffix: false` devolve só o intervalo ("5 minutos"), como o inbox lê.
 * Data inválida → `—`.
 */
export function formatRelativeTime(
  date: Date | string | number | null | undefined,
  options?: { addSuffix?: boolean }
): string {
  const d = toValidDate(date);
  if (!d) return DATA_INVALIDA;
  return formatDistanceToNow(d, { addSuffix: options?.addSuffix ?? true, locale: ptBR });
}

/**
 * Format a date as a smart label: "Hoje", "Ontem", or full date.
 * Data inválida → `—`.
 */
export function formatSmartDate(date: Date | string | null | undefined): string {
  const d = toValidDate(date);
  if (!d) return DATA_INVALIDA;
  if (isToday(d)) return `Hoje, ${format(d, 'HH:mm', { locale: ptBR })}`;
  if (isYesterday(d)) return `Ontem, ${format(d, 'HH:mm', { locale: ptBR })}`;
  return format(d, "dd/MM/yyyy 'às' HH:mm", { locale: ptBR });
}

/**
 * Format a date as short date (dd/MM/yyyy). Data inválida → `—`.
 */
export function formatShortDate(date: Date | string | null | undefined): string {
  const d = toValidDate(date);
  if (!d) return DATA_INVALIDA;
  return format(d, 'dd/MM/yyyy', { locale: ptBR });
}

/**
 * Format a date as full datetime. Data inválida → `—`.
 */
export function formatFullDateTime(date: Date | string | null | undefined): string {
  const d = toValidDate(date);
  if (!d) return DATA_INVALIDA;
  return format(d, "dd/MM/yyyy 'às' HH:mm:ss", { locale: ptBR });
}

// ─── Phone Formatting ───────────────────────────────────────────────

/**
 * Clean phone number to digits only (removes +, spaces, dashes, parens)
 */
export function cleanPhone(phone: string): string {
  return phone.replace(/\D/g, '');
}

/**
 * Format a Brazilian phone number: (11) 99999-9999
 */
export function formatBrazilianPhone(phone: string): string {
  const digits = cleanPhone(phone);
  // Remove country code 55 if present
  const local = digits.startsWith('55') && digits.length > 11 ? digits.slice(2) : digits;
  if (local.length === 11) {
    return `(${local.slice(0, 2)}) ${local.slice(2, 7)}-${local.slice(7)}`;
  }
  if (local.length === 10) {
    return `(${local.slice(0, 2)}) ${local.slice(2, 6)}-${local.slice(6)}`;
  }
  return phone; // Return original if format unknown
}

// ─── Currency Formatting ────────────────────────────────────────────

/**
 * Format a number as Brazilian Real (R$ 1.234,56)
 */
export function formatBRL(value: number): string {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
}

// ─── Text Formatting ────────────────────────────────────────────────

/**
 * Truncate text with ellipsis
 */
export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength).trimEnd() + '…';
}

/**
 * Get initials from a name (e.g., "João Silva" → "JS")
 */
export function getInitials(name: string, maxChars = 2): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, maxChars)
    // `codePointAt(0)` + `fromCodePoint` pegam o primeiro CARACTERE (code
    // point), não o primeiro par de surrogates: `word[0]` partia o emoji ao
    // meio ("😀Ana" virava o caractere quebrado, não "😀").
    .map((word) => String.fromCodePoint(word.codePointAt(0)!).toUpperCase())
    .join('');
}

// ─── Number Formatting ──────────────────────────────────────────────

/**
 * Format large numbers with K/M suffix (e.g., 1500 → "1.5K")
 */
export function formatCompactNumber(value: number): string {
  return new Intl.NumberFormat('pt-BR', {
    notation: 'compact',
    maximumFractionDigits: 1,
  }).format(value);
}

/**
 * Format a duration in seconds to human-readable (e.g., 125 → "2min 5s")
 */
export function formatDuration(seconds: number): string {
  if (seconds < 60) return `${Math.round(seconds)}s`;
  const mins = Math.floor(seconds / 60);
  const secs = Math.round(seconds % 60);
  if (mins < 60) return secs > 0 ? `${mins}min ${secs}s` : `${mins}min`;
  const hours = Math.floor(mins / 60);
  const remainMins = mins % 60;
  return remainMins > 0 ? `${hours}h ${remainMins}min` : `${hours}h`;
}

/**
 * Format percentage (e.g., 0.856 → "85.6%")
 */
export function formatPercentage(value: number, decimals = 1): string {
  return `${(value * 100).toFixed(decimals)}%`;
}

/**
 * Data de nascimento para o sidebar: `{ label: 'dd/MM/yyyy', age }`.
 * Idade em anos completos; `null` para data inválida ou futura (nunca
 * inventa — a UI mostra "—").
 */
export function formatBirthday(iso: string | null | undefined, now: Date = new Date()): { label: string | null; age: number | null } {
  if (!iso) return { label: null, age: null };
  // 'YYYY-MM-DD' precisa ser lido como data local (new Date(iso) interpreta
  // como UTC e o dd/MM viraria o dia anterior em GMT-3). O construtor
  // numérico NORMALIZA datas impossíveis (2025-02-30 → 02/03) e anos 0-99
  // (→ 1900+), então a data só vale se os componentes baterem de volta.
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso.trim());
  let date: Date;
  if (dateOnly) {
    const [y, m, d] = [Number(dateOnly[1]), Number(dateOnly[2]), Number(dateOnly[3])];
    const parsed = new Date(y, m - 1, d);
    if (parsed.getFullYear() !== y || parsed.getMonth() !== m - 1 || parsed.getDate() !== d) {
      return { label: null, age: null };
    }
    date = parsed;
  } else {
    date = new Date(iso);
  }
  if (Number.isNaN(date.getTime())) return { label: null, age: null };
  if (date.getTime() > now.getTime()) return { label: format(date, 'dd/MM/yyyy', { locale: ptBR }), age: null };
  let age = now.getFullYear() - date.getFullYear();
  // 29/02 em ano comum: o aniversário conta no dia 28/02 (new Date(y,1,29)
  // normalizaria para 01/03 e atrasaria a idade um dia).
  const month = date.getMonth();
  const day = date.getDate();
  const dayThisYear = month === 1 && day === 29 && new Date(now.getFullYear(), 1, 29).getDate() !== 29 ? 28 : day;
  const birthdayThisYear = new Date(now.getFullYear(), month, dayThisYear);
  if (birthdayThisYear.getTime() > now.getTime()) age -= 1;
  return { label: format(date, 'dd/MM/yyyy', { locale: ptBR }), age };
}
